=== merge_sort
#include <assert.h>

#define N 4

int nondet_int(void);

static void merge(int *a, int lo, int mid, int hi, int *tmp) {
    int i = lo, j = mid, k = lo;
    while (i < mid && j < hi) tmp[k++] = (a[i] <= a[j]) ? a[i++] : a[j++];
    while (i < mid) tmp[k++] = a[i++];
    while (j < hi) tmp[k++] = a[j++];
    for (k = lo; k < hi; k++) a[k] = tmp[k];
}

static void msort(int *a, int lo, int hi, int *tmp) {
    if (hi - lo < 2) return;
    int mid = lo + (hi - lo) / 2;
    msort(a, lo, mid, tmp);
    msort(a, mid, hi, tmp);
    merge(a, lo, mid, hi, tmp);
}

int main(void) {
    int a[N], orig[N], tmp[N];
    for (int i = 0; i < N; i++) {
        a[i] = nondet_int();
        __ESBMC_assume(a[i] >= 0 && a[i] < 8);
        orig[i] = a[i];
    }

    msort(a, 0, N, tmp);

    for (int i = 0; i + 1 < N; i++)
        assert(a[i] <= a[i + 1]);                       /* sorted */

    for (int i = 0; i < N; i++) {                        /* permutation */
        int ci = 0, co = 0;
        for (int j = 0; j < N; j++) {
            ci += (orig[j] == orig[i]);
            co += (a[j] == orig[i]);
        }
        assert(ci == co);
    }
    return 0;
}
=== utf8_decode
#include <assert.h>
#include <stdint.h>

unsigned nondet_uint(void);
unsigned char nondet_uchar(void);

int utf8_decode(const unsigned char *b, unsigned len, uint32_t *cp) {
    if (len == 0) return 0;
    unsigned char lead = b[0];
    uint32_t c, min;
    int n;
    if (lead < 0x80) { *cp = lead; return 1; }          /* ASCII */
    else if ((lead & 0xE0) == 0xC0) { c = lead & 0x1F; n = 2; min = 0x80; }
    else if ((lead & 0xF0) == 0xE0) { c = lead & 0x0F; n = 3; min = 0x800; }
    else if ((lead & 0xF8) == 0xF0) { c = lead & 0x07; n = 4; min = 0x10000; }
    else return 0;                                      /* stray 0x80..0xBF or 0xF8..0xFF */

    for (int i = 1; i < n; i++) {
        if ((unsigned)i >= len) return 0;               /* truncated */
        unsigned char cb = b[i];
        if ((cb & 0xC0) != 0x80) return 0;              /* bad continuation byte */
        c = (c << 6) | (cb & 0x3F);
    }
    if (c < min) return 0;                              /* overlong */
    if (c >= 0xD800 && c <= 0xDFFF) return 0;           /* surrogate */
    if (c > 0x10FFFF) return 0;                         /* out of Unicode range */
    *cp = c;
    return n;
}

int main(void) {
    unsigned len = nondet_uint();
    __ESBMC_assume(len >= 1 && len <= 4);
    unsigned char b[len];
    for (unsigned i = 0; i < len; i++) b[i] = nondet_uchar();

    uint32_t cp = 0;
    int n = utf8_decode(b, len, &cp);
    if (n > 0) {
        assert((unsigned)n <= len);
        assert(cp <= 0x10FFFF);
        assert(cp < 0xD800 || cp > 0xDFFF);
    }
    return 0;
}
=== murmurhash
#include <stdint.h>
#include <stddef.h>

#define MAXLEN 8

unsigned nondet_uint(void);
unsigned char nondet_uchar(void);

static uint32_t rotl32(uint32_t x, int8_t r) {
    return (x << r) | (x >> (32 - r));
}

static uint32_t murmur3_32(const uint8_t *key, size_t len, uint32_t seed) {
    uint32_t h = seed;
    const uint32_t c1 = 0xcc9e2d51, c2 = 0x1b873593;
    size_t nblocks = len / 4;

    for (size_t i = 0; i < nblocks; i++) {
        const uint8_t *p = key + i * 4;
        uint32_t k = (uint32_t)p[0] | ((uint32_t)p[1] << 8) |
                     ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
        k *= c1; k = rotl32(k, 15); k *= c2;
        h ^= k; h = rotl32(h, 13); h = h * 5 + 0xe6546b64;
    }

    const uint8_t *tail = key + nblocks * 4;
    uint32_t k1 = 0;
    switch (len & 3) {
        case 3: k1 ^= (uint32_t)tail[2] << 16; /* fallthrough */
        case 2: k1 ^= (uint32_t)tail[1] << 8;  /* fallthrough */
        case 1: k1 ^= (uint32_t)tail[0];
                k1 *= c1; k1 = rotl32(k1, 15); k1 *= c2; h ^= k1;
    }

    h ^= (uint32_t)len;
    h ^= h >> 16; h *= 0x85ebca6b; h ^= h >> 13; h *= 0xc2b2ae35; h ^= h >> 16;
    return h;
}

int main(void) {
    unsigned len = nondet_uint();
    __ESBMC_assume(len >= 1 && len <= MAXLEN);
    uint8_t key[len];                       /* sized to the logical length */
    for (unsigned i = 0; i < len; i++) key[i] = nondet_uchar();

    /* Property is the memory safety of murmur3_32's reads (default array-bounds
     * checks against the len-sized object); (void)h keeps the call live so the
     * reads are not sliced away. */
    uint32_t h = murmur3_32(key, len, 0);
    (void)h;
    return 0;
}
=== frame_checksum
#include <stddef.h>
#include <stdint.h>

#define HEADER_BYTES 2

static uint32_t sum_bytes(const uint8_t *buf, size_t len) {
    uint32_t acc = 0;
    for (size_t i = 0; i < len; i++) {
        acc += buf[i];
    }
    return acc;
}

uint32_t frame_checksum(const uint8_t *frame, size_t len) {
    return sum_bytes(frame, len);
}

uint32_t payload_checksum(const uint8_t *frame, size_t len) {
    if (len < HEADER_BYTES) {
        return 0;
    }
    return sum_bytes(frame + HEADER_BYTES, len - HEADER_BYTES);
}
